select m.id,v.k,v.t,v.ft,v.r,v.s,v.o::jsonb from platform_modules m cross join (values
('compliance-code','کد کنترل انطباق','text',true,10,'{}'),('document-code','کد سند','text',true,20,'{}'),('document-title','عنوان سند','text',true,30,'{}'),('requirement-code','کد الزام','text',true,40,'{}'),('requirement-title','عنوان الزام','text',true,50,'{}'),('requirement-type','نوع الزام','select',true,60,'{"options":["قانونی","مقرراتی","سازمانی","قراردادی","امنیتی","حفاظت داده","کیفی"]}'),('authority','مرجع الزام','text',false,70,'{}'),('control-type','نوع کنترل','select',true,80,'{"options":["مستندات اجباری","تأیید دوره‌ای","سطح دسترسی","نگهداری","نسخه معتبر","ثبت رویداد","بازبینی"]}'),('owner','مسئول کنترل','text',true,90,'{}'),('review-date','تاریخ بازبینی','text',false,100,'{}'),('due-date','مهلت اقدام','text',false,110,'{}'),('compliance-status','وضعیت انطباق','select',true,120,'{"options":["منطبق","منطبق با اصلاحات","غیرمنطبق","در حال بررسی","منقضی","معاف"]}'),('risk-level','سطح ریسک','select',true,130,'{"options":["عادی","کم","متوسط","زیاد","بحرانی"]}'),('evidence-reference','مرجع مستندات اثبات','text',false,140,'{}'),('finding','یافته / مغایرت','textarea',false,150,'{}'),('corrective-action','اقدام اصلاحی','textarea',false,160,'{}'),('closure-date','تاریخ رفع مغایرت','text',false,170,'{}'),('notes','یادداشت','textarea',false,180,'{}')
) v(k,t,ft,r,s,o) where m.code='49-document-compliance' on conflict(module_id,field_key) do update set title=excluded.title,field_type=excluded.field_type,required=excluded.required,sort_order=excluded.sort_order,options=excluded.options;
