insert into platform_modules(code,title,is_active) values ('49-document-compliance','کنترل انطباق و الزامات مستندات',true) on conflict(code) do update set title=excluded.title,is_active=true;
insert into module_field_definitions(module_id,field_key,title,field_type,required,sort_order,options)
insert into module_actions(module_id,action_code,title,permission) select m.id,v.a,v.t,v.p from platform_modules m cross join (values
('read','مشاهده کنترل‌ها','modules:49-document-compliance:read'),('write','ثبت کنترل','modules:49-document-compliance:write'),('delete','حذف کنترل','modules:49-document-compliance:delete'),('assess','ارزیابی انطباق','modules:49-document-compliance:assess'),('correct','ثبت اقدام اصلاحی','modules:49-document-compliance:correct'),('close','بستن مغایرت','modules:49-document-compliance:close'),('waive','ثبت معافیت','modules:49-document-compliance:waive')) v(a,t,p) where m.code='49-document-compliance' on conflict(module_id,action_code) do update set title=excluded.title,permission=excluded.permission;